'use client';

/**
 * Activity table — a full data-table page: search, status filter, sortable columns, row selection with bulk
 * actions, CSV export of the current view, row density, pagination, and empty and loading states (Refresh shows
 * the skeleton while it "reloads"). Built only from Strata components; copy and rows come from `content`.
 *
 * `headingLevel` (default 1) is the level of the page title. Above 1 the block is embedded in another page and
 * renders no <main> landmark.
 */

import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { DataTable, DataTablePagination, DataTableToolbar, useSortedRows, type DataTableColumn, type DataTableSelection, type DataTableSortDescriptor } from '@/components/ui/data-table';
import { EmptyState } from '@/components/ui/empty-state';
import { Menu, MenuItem, MenuTrigger } from '@/components/ui/menu';
import { SearchField } from '@/components/ui/search-field';
import { Select, SelectItem } from '@/components/ui/select';
import { ToastRegion, toast } from '@/components/ui/toast';
import { ToggleButton, ToggleButtonGroup } from '@/components/ui/toggle-group';
import { Tooltip, TooltipTrigger } from '@/components/ui/tooltip';
import {
  IconBaselineDensityMedium,
  IconBaselineDensitySmall,
  IconChevronDown,
  IconDownload,
  IconRefresh,
  IconSearch,
} from '@tabler/icons-react';
import { useId, useLayoutEffect, useMemo, useRef, useState, type HTMLAttributes, type JSX, type RefObject } from 'react';
import { activityTableContent, type ActivityPlural, type ActivityRow, type ActivityTableContent } from './activity-table.content';
import styles from './activity-table.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

type Level = 1 | 2 | 3 | 4 | 5 | 6;
const level = (n: number): Level => Math.min(6, Math.max(1, Math.round(n))) as Level;
const subLevel = (n: number) => Math.min(6, Math.max(2, Math.round(n))) as Exclude<Level, 1>;

function Heading({ level: l, ...rest }: { level: Level } & HTMLAttributes<HTMLHeadingElement>): JSX.Element {
  const Tag = `h${l}` as const;
  return <Tag {...rest} />;
}

const PAGE_SIZE = 8;
/** Below this width (px) the table folds date, category and status into two columns. */
const COMPACT_TABLE_BELOW = 640;
const ALL = '__all';

type Density = 'comfortable' | 'compact';

function useWidthBelow(ref: RefObject<HTMLElement | null>, width: number): boolean {
  const [below, setBelow] = useState(false);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(([entry]) => {
      if (entry) setBelow(entry.contentRect.width < width);
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref, width]);
  return below;
}

/* ------------------------------------------------------------------ *
 * Formatting — Intl in the content locale
 * ------------------------------------------------------------------ */

const MINUS = '−';

function useFormat(locale: string, currency: string) {
  return useMemo(() => {
    const signed = new Intl.NumberFormat(locale, { style: 'currency', currency, signDisplay: 'exceptZero' });
    const number = new Intl.NumberFormat(locale);
    const day = new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });
    const plural = new Intl.PluralRules(locale);
    return {
      amount: (v: number) =>
        signed
          .formatToParts(v)
          .map((p) => (p.type === 'minusSign' ? p.value.replace('-', MINUS) : p.value))
          .join(''),
      date: (iso: string) => {
        const d = new Date(`${iso}T00:00:00Z`);
        return Number.isNaN(d.getTime()) ? iso : day.format(d);
      },
      number: (n: number) => number.format(n),
      count: (n: number, forms: ActivityPlural) =>
        (forms[plural.select(n) as keyof ActivityPlural] ?? forms.other).replace('{count}', number.format(n)),
    };
  }, [locale, currency]);
}

/** Quotes a CSV field when it contains a separator, quote or line break. */
const csvCell = (v: string | number) => {
  const s = String(v);
  return /[",\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
};

/* ------------------------------------------------------------------ *
 * Block
 * ------------------------------------------------------------------ */

export interface ActivityTableProps {
  /** All copy and rows. Defaults to the English sample in ./activity-table.content.ts. */
  content?: ActivityTableContent;
  /** Level of the page title (default 1). Above 1 the block renders as embedded: no <main>. */
  headingLevel?: 1 | 2 | 3 | 4;
  /** Shows the skeleton rows, e.g. while your rows load. Refresh also shows them briefly. */
  isLoading?: boolean;
  className?: string;
}

export function ActivityTable({
  content = activityTableContent,
  headingLevel = 1,
  isLoading = false,
  className,
}: ActivityTableProps): JSX.Element {
  const uid = useId();
  const a = content.activity;
  const fmt = useFormat(content.locale, content.currency);
  const embedded = headingLevel > 1;
  const Main = embedded ? 'div' : 'main';

  const rootRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const compact = useWidthBelow(cardRef, COMPACT_TABLE_BELOW);

  const [query, setQuery] = useState('');
  const [status, setStatus] = useState<string>(ALL);
  const [sort, setSort] = useState<DataTableSortDescriptor>({ column: 'date', direction: 'descending' });
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [refreshing, setRefreshing] = useState(false);
  const loading = isLoading || refreshing;
  const [density, setDensity] = useState<Density | undefined>();

  // Start the density toggle on the theme's own density: compare its table row height with the comfortable one.
  useLayoutEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const style = getComputedStyle(el);
    const row = parseFloat(style.getPropertyValue('--strata-table-row-height'));
    const comfortable = parseFloat(style.getPropertyValue('--strata-space-12'));
    if (Number.isFinite(row) && Number.isFinite(comfortable)) setDensity(row >= comfortable ? 'comfortable' : 'compact');
  }, []);

  const filtered = useMemo(() => {
    const q = query.trim().toLocaleLowerCase(content.locale);
    return a.rows.filter(
      (row) =>
        (status === ALL || row.status === status) &&
        (!q || [row.title, row.meta, row.category, row.id].some((v) => v.toLocaleLowerCase(content.locale).includes(q))),
    );
  }, [a.rows, query, status, content.locale]);

  const accessors = useMemo(
    () => ({
      date: (r: ActivityRow) => r.date,
      description: (r: ActivityRow) => r.title,
      category: (r: ActivityRow) => r.category,
      status: (r: ActivityRow) => a.statuses[r.status]?.label ?? r.status,
      amount: (r: ActivityRow) => r.amount,
    }),
    [a.statuses],
  );
  const sorted = useSortedRows(filtered, sort, accessors);
  const pageCount = Math.max(1, Math.ceil(sorted.length / PAGE_SIZE));
  const current = Math.min(page, pageCount);
  const pageRows = sorted.slice((current - 1) * PAGE_SIZE, current * PAGE_SIZE);

  const resetView = () => {
    setPage(1);
    setSelected(new Set());
  };

  const onSelectionChange = (keys: DataTableSelection) => {
    // "Select all" in the header means the rows on this page.
    setSelected(keys === 'all' ? new Set(pageRows.map((r) => r.id)) : new Set([...keys].map(String)));
  };

  const refresh = () => {
    setRefreshing(true);
    setSelected(new Set());
    // Stands in for refetching.
    setTimeout(() => setRefreshing(false), 1400);
  };

  const exportCsv = () => {
    const header = [a.columns.date, a.columns.description, a.columns.category, a.columns.status, a.columns.amount, 'ID'];
    const lines = sorted.map((r) =>
      [r.date, `${r.title} · ${r.meta}`, r.category, a.statuses[r.status]?.label ?? r.status, r.amount, r.id].map(csvCell).join(','),
    );
    // BOM so spreadsheet apps read non-Latin text (Arabic, Hindi…) as UTF-8.
    const blob = new Blob(['﻿' + [header.map(csvCell).join(','), ...lines].join('\r\n')], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'activity.csv';
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 0);
    toast({ title: fmt.count(sorted.length, a.exported), tone: 'success' });
  };

  const columns = useMemo<DataTableColumn<ActivityRow>[]>(() => {
    const statusBadge = (row: ActivityRow) => {
      const s = a.statuses[row.status] ?? { label: row.status, tone: 'neutral' as const };
      return (
        <Badge tone={s.tone} size={compact ? 'sm' : 'md'}>
          {s.label}
        </Badge>
      );
    };
    const description: DataTableColumn<ActivityRow> = {
      id: 'description',
      header: a.columns.description,
      isRowHeader: true,
      allowsSorting: true,
      cell: (row) => (
        <span className={styles.desc}>
          <span className={styles.descTitle}>{row.title}</span>
          <span className={styles.descMeta}>{compact ? `${fmt.date(row.date)} · ${row.meta}` : row.meta}</span>
        </span>
      ),
    };
    const amount: DataTableColumn<ActivityRow> = {
      id: 'amount',
      header: a.columns.amount,
      align: 'end',
      allowsSorting: true,
      cell: (row) =>
        compact ? (
          <span className={styles.amountStack}>
            <span className={cx(styles.amount, row.amount > 0 && styles.amountIn)}>{fmt.amount(row.amount)}</span>
            {statusBadge(row)}
          </span>
        ) : (
          <span className={cx(styles.amount, row.amount > 0 && styles.amountIn)}>{fmt.amount(row.amount)}</span>
        ),
    };
    if (compact) return [description, amount];
    return [
      { id: 'date', header: a.columns.date, allowsSorting: true, cell: (row) => <time dateTime={row.date}>{fmt.date(row.date)}</time> },
      description,
      { id: 'category', header: a.columns.category, allowsSorting: true, cell: (row) => row.category },
      { id: 'status', header: a.columns.status, allowsSorting: true, cell: statusBadge },
      amount,
    ];
  }, [a.columns, a.statuses, compact, fmt]);

  const count = selected.size;
  const { pagination: p } = a;

  return (
    <div ref={rootRef} className={cx(styles.root, className)}>
      <Main className={styles.page} aria-labelledby={embedded ? undefined : `${uid}-title`}>
        <div className={styles.header}>
          <div className={styles.titleBlock}>
            <Heading level={level(headingLevel)} id={`${uid}-title`} className={styles.title}>
              {a.title}
            </Heading>
            <p className={styles.description}>{a.description}</p>
          </div>
          <div className={styles.headerActions}>
            <Button variant="outline" onPress={refresh} isDisabled={loading}>
              <IconRefresh aria-hidden />
              {a.refresh}
            </Button>
            <Button variant="primary" onPress={exportCsv} isDisabled={loading || sorted.length === 0}>
              <IconDownload aria-hidden />
              {a.export}
            </Button>
          </div>
        </div>

        <Card className={styles.card} ref={cardRef}>
          <DataTableToolbar className={styles.toolbar}>
            <div className={styles.filters}>
              <SearchField
                aria-label={a.search.label}
                placeholder={a.search.placeholder}
                value={query}
                onChange={(v) => {
                  setQuery(v);
                  resetView();
                }}
                className={styles.search}
              />
              <Select
                aria-label={a.status.label}
                selectedKey={status}
                onSelectionChange={(key) => {
                  setStatus(key == null ? ALL : String(key));
                  resetView();
                }}
                className={styles.status}
              >
                <SelectItem id={ALL}>{a.status.all}</SelectItem>
                {Object.entries(a.statuses).map(([id, s]) => (
                  <SelectItem key={id} id={id}>
                    {s.label}
                  </SelectItem>
                ))}
              </Select>
            </div>
            <div className={styles.tools}>
              <span className={styles.selection} aria-live="polite">
                {count > 0 ? fmt.count(count, a.selected) : ''}
              </span>
              <MenuTrigger>
                <Button variant="outline" isDisabled={count === 0} className={styles.bulk}>
                  {a.bulk.label}
                  <IconChevronDown aria-hidden />
                </Button>
                <Menu
                  placement="bottom end"
                  onAction={(key) => {
                    const item = a.bulk.items.find((i) => i.id === key);
                    if (!item) return;
                    toast({ title: fmt.count(count, item.done), tone: 'success' });
                    setSelected(new Set());
                  }}
                >
                  {a.bulk.items.map((item) => (
                    <MenuItem key={item.id} id={item.id}>
                      {item.label}
                    </MenuItem>
                  ))}
                </Menu>
              </MenuTrigger>
              <ToggleButtonGroup
                aria-label={a.density.label}
                size="sm"
                selectedKeys={density ? [density] : []}
                disallowEmptySelection
                onSelectionChange={(keys) => {
                  const [next] = keys;
                  if (next === 'comfortable' || next === 'compact') setDensity(next);
                }}
              >
                <TooltipTrigger delay={500}>
                  <ToggleButton id="comfortable" aria-label={a.density.comfortable}>
                    <IconBaselineDensityMedium aria-hidden />
                  </ToggleButton>
                  <Tooltip>{a.density.comfortable}</Tooltip>
                </TooltipTrigger>
                <TooltipTrigger delay={500}>
                  <ToggleButton id="compact" aria-label={a.density.compact}>
                    <IconBaselineDensitySmall aria-hidden />
                  </ToggleButton>
                  <Tooltip>{a.density.compact}</Tooltip>
                </TooltipTrigger>
              </ToggleButtonGroup>
            </div>
          </DataTableToolbar>

          <DataTable
            aria-labelledby={`${uid}-title`}
            columns={columns}
            rows={pageRows}
            getRowId={(row) => row.id}
            selectionMode="multiple"
            selectedKeys={selected}
            onSelectionChange={onSelectionChange}
            sortDescriptor={sort}
            onSortChange={(next) => {
              setSort(next);
              setPage(1);
            }}
            isLoading={loading}
            loadingRowCount={PAGE_SIZE}
            loadingLabel={a.loading}
            density={density}
            stickyHeader={false}
            className={styles.table}
            emptyState={
              <EmptyState
                size="sm"
                level={subLevel(headingLevel + 1)}
                icon={<IconSearch />}
                title={a.empty.title}
                description={a.empty.description}
                action={
                  <Button
                    variant="outline"
                    size="sm"
                    onPress={() => {
                      setQuery('');
                      setStatus(ALL);
                      resetView();
                    }}
                  >
                    {a.empty.clear}
                  </Button>
                }
              />
            }
          />

          <DataTablePagination
            className={styles.pagination}
            label={p.label}
            previousLabel={p.previous}
            nextLabel={p.next}
            pageLabel={p.page}
            ofLabel={p.of}
            page={current}
            pageSize={PAGE_SIZE}
            totalCount={sorted.length}
            onPageChange={(next) => {
              setPage(next);
              setSelected(new Set());
            }}
            formatSummary={({ start, end, total }) =>
              total === 0
                ? p.none
                : p.summary
                    .replace('{start}', fmt.number(start))
                    .replace('{end}', fmt.number(end))
                    .replace('{total}', fmt.number(total))
            }
          />
        </Card>
      </Main>
      <ToastRegion />
    </div>
  );
}

/*
 * Activity table. Tokens only; container breakpoints are the only literals (CSS can't read them from variables).
 */

.root {
  --_page: calc(var(--strata-space-16) * 20);
  --_gutter: var(--strata-space-4);

  container: activity-table / inline-size;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-block-size: 100%;
  background-color: var(--strata-color-surface-canvas);
  color: var(--strata-color-text-default);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  text-align: start;
}

.root :where(*, *::before, *::after) {
  box-sizing: border-box;
}

.root :where(h1, h2, h3, h4, h5, h6, p) {
  margin: 0;
}

@container activity-table (min-width: 640px) {
  .root > * {
    --_gutter: var(--strata-space-6);
  }
}

@container activity-table (min-width: 1024px) {
  .root > * {
    --_gutter: var(--strata-space-8);
  }
}

.page {
  flex: 1;
  display: grid;
  align-content: start;
  gap: var(--strata-space-6);
  inline-size: 100%;
  max-inline-size: var(--_page);
  margin-inline: auto;
  padding-block: var(--strata-space-6) var(--strata-space-12);
  padding-inline: var(--_gutter);
}

@container activity-table (min-width: 1024px) {
  .page {
    padding-block-start: var(--strata-space-10);
  }
}

.header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--strata-space-4);
}

.titleBlock {
  display: grid;
  gap: var(--strata-space-1);
  flex: 1 1 calc(var(--strata-space-16) * 5);
  min-inline-size: 0;
}

.title {
  font-family: var(--strata-font-heading);
  font-size: var(--strata-font-size-xl);
  font-weight: var(--strata-font-weight-semibold);
  letter-spacing: var(--strata-font-heading-tracking);
  line-height: var(--strata-line-height-tight);
}

@container activity-table (min-width: 640px) {
  .title {
    font-size: var(--strata-font-size-2xl);
  }
}

.description {
  color: var(--strata-color-text-subtle);
  text-wrap: pretty;
}

.headerActions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--strata-space-2);
}

@container activity-table (max-width: 479.98px) {
  .headerActions {
    inline-size: 100%;
  }

  .headerActions > * {
    flex: 1 1 0;
  }
}

/* ------------------------------------------------------------------ *
 * Card: toolbar, edge-to-edge table, pagination
 * ------------------------------------------------------------------ */

.card.card {
  gap: 0;
  padding-block: 0;
  overflow: hidden;
}

.toolbar.toolbar {
  padding: var(--strata-card-inset);
}

.filters {
  display: flex;
  flex: 1 1 calc(var(--strata-space-16) * 6);
  flex-wrap: wrap;
  gap: var(--strata-space-2);
  min-inline-size: 0;
}

.search.search {
  flex: 1 1 calc(var(--strata-space-16) * 4);
  min-inline-size: 0;
  max-inline-size: calc(var(--strata-space-16) * 6);
}

.status.status {
  flex: 0 1 calc(var(--strata-space-16) * 3);
  min-inline-size: calc(var(--strata-space-16) * 2.5);
}

.tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--strata-space-2);
}

.selection {
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.selection:empty {
  display: none;
}

.bulk.bulk {
  gap: var(--strata-space-1);
}

.table.table {
  border: 0;
  border-block: 1px solid var(--strata-color-border-subtle);
  border-radius: 0;
  background-color: transparent;
}

.pagination.pagination {
  padding-block: var(--strata-space-3);
  padding-inline: var(--strata-card-inset);
}

.desc {
  display: grid;
  min-inline-size: 0;
}

.descTitle {
  overflow: hidden;
  font-weight: var(--strata-font-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.descMeta {
  overflow: hidden;
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.amount {
  font-variant-numeric: tabular-nums;
  font-weight: var(--strata-font-weight-medium);
  white-space: nowrap;
}

.amountIn {
  color: var(--strata-color-feedback-success-fg);
}

.amountStack {
  display: inline-grid;
  justify-items: end;
  gap: var(--strata-space-1);
}

/*
 * Selected rows sit on surface.selected (darker still while hovered), which the theme's contrast pairs don't
 * cover for secondary text or feedback colours. Use the default text colour there; the sign and the label carry
 * the meaning.
 */
[data-selected] .descMeta,
[data-selected] .amountIn {
  color: var(--strata-color-text-default);
}

/**
 * Content for the activity-table block: every label and row. Replace this object to translate or rebrand it.
 * Amounts are signed numbers in `currency`, dates are ISO; both are formatted with Intl in `locale`. Counts use
 * plural forms chosen by Intl.PluralRules, so languages with more than two forms (Arabic has six) read naturally.
 */

/** Plural forms keyed by Intl.PluralRules category; `{count}` is replaced with the formatted number. */
export type ActivityPlural = { other: string } & Partial<Record<'zero' | 'one' | 'two' | 'few' | 'many', string>>;

export type ActivityTone = 'success' | 'warning' | 'danger' | 'info' | 'neutral';

export interface ActivityRow {
  /** Unique row id, e.g. a transaction reference. */
  id: string;
  /** ISO date. */
  date: string;
  title: string;
  /** Secondary line under the title. */
  meta: string;
  category: string;
  /** Key into `statuses`. */
  status: string;
  /** Signed amount in `currency`. Negative = money out. */
  amount: number;
}

export interface ActivityTableContent {
  /** BCP 47 locale for numbers and dates. */
  locale: string;
  /** ISO 4217 currency code. */
  currency: string;
  product: { name: string };
  activity: {
    title: string;
    description: string;
    export: string;
    /** Toast after exporting. */
    exported: ActivityPlural;
    refresh: string;
    search: { label: string; placeholder: string };
    status: { label: string; all: string };
    density: { label: string; comfortable: string; compact: string };
    /** Menu of actions on the selected rows; each has its own confirmation toast. */
    bulk: { label: string; items: { id: string; label: string; done: ActivityPlural }[] };
    /** "3 selected". */
    selected: ActivityPlural;
    columns: { date: string; description: string; category: string; status: string; amount: string };
    statuses: Record<string, { label: string; tone: ActivityTone }>;
    rows: ActivityRow[];
    empty: { title: string; description: string; clear: string };
    pagination: {
      label: string;
      previous: string;
      next: string;
      page: string;
      of: string;
      /** `{start}`, `{end}` and `{total}` are replaced with formatted numbers. */
      summary: string;
      none: string;
    };
    /** Read by screen readers on skeleton rows. */
    loading: string;
  };
}

export const activityTableContent: ActivityTableContent = {
  locale: 'en-US',
  currency: 'USD',
  product: { name: 'Acme' },
  activity: {
    title: 'Transactions',
    description: 'Every payment in and out of your account.',
    export: 'Export CSV',
    exported: { one: 'Exported {count} transaction', other: 'Exported {count} transactions' },
    refresh: 'Refresh',
    search: { label: 'Search transactions', placeholder: 'Search by name, reference or category' },
    status: { label: 'Status', all: 'All statuses' },
    density: { label: 'Row density', comfortable: 'Comfortable', compact: 'Compact' },
    bulk: {
      label: 'Bulk actions',
      items: [
        { id: 'review', label: 'Mark as reviewed', done: { one: '{count} transaction marked as reviewed', other: '{count} transactions marked as reviewed' } },
        { id: 'report', label: 'Add to expense report', done: { one: 'Added {count} transaction to your expense report', other: 'Added {count} transactions to your expense report' } },
      ],
    },
    selected: { one: '{count} selected', other: '{count} selected' },
    columns: { date: 'Date', description: 'Description', category: 'Category', status: 'Status', amount: 'Amount' },
